import json, os
caps = json.loads(os.environ['CAPS']); gt = json.loads(os.environ['GT'])
R = '/scratch/jjyeung'; lst = []; nb = 0; miss = 0; nm = 0; byg = {}
for sc in caps:
    name = sc.replace('/', '__'); found = None
    for g in ('g3s32', 'g3s64'):
        p = '%s/devs1_r2/anchors/%s/%s/A_MANIFEST.json' % (R, g, name)
        if os.path.exists(p): found = p; break
    if not found: nm += 1; continue
    lst.append(found[len(R) + 1:])
    for f in json.load(open(found))['selections'][0]['frames']:
        q = '%s/devs1_frames/%s' % (R, f['path'])
        if os.path.exists(q): lst.append(q[len(R) + 1:]); nb += os.path.getsize(q)
        else: miss += 1
g_ok = 0
for cap, p in gt:
    if os.path.exists(p): lst.append(p[len(R) + 1:]); nb += os.path.getsize(p); g_ok += 1
open('/scratch/jjyeung/orch_n30/nvkey1/c0_files.txt', 'w').write('\n'.join(lst) + '\n')
print('manifests missing', nm, 'frame files', sum(1 for x in lst if x.startswith('devs1_frames')), 'frames missing', miss, 'gt present', g_ok, 'of', len(gt), 'bytes', nb)
PY
